<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LSZJ Flugfreigaben</title><link rel="stylesheet" href="app.css"><link rel="stylesheet" href="correction_ux.css"></head><body><h1>Flugfreigaben</h1><div class="nav"><a href="#" onclick="nav('dashboard.php');return false;">Dashboard</a><a href="#" onclick="nav('flight_approvals.php');return false;">Flugfreigaben</a><a href="#" onclick="nav('manual_flight.php');return false;">+ Flug manuell erfassen</a></div><div class="top"><label>Von <input id="from" type="date"></label><label>Bis <input id="to" type="date"></label><label>Status <select id="status"><option value="pending">pending</option><option value="correction_required">correction_required</option><option value="approved">approved</option><option value="all">all</option></select></label><label>Benutzer <input id="user" value="demo"></label><button onclick="loadData()">Laden</button><button class="secondary" onclick="importKTraxRange()">kTrax-Import</button><button class="secondary" onclick="setToday()">Heute</button><button class="secondary" onclick="setYesterday()">Gestern</button><button class="secondary" onclick="setLast7()">Letzte 7 Tage</button></div><div id="rangeLabel" class="card"></div><div id="metrics" class="grid"></div><div id="list"></div><script>
function qs(id){return document.getElementById(id)}function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function getParam(n,f){const p=new URLSearchParams(location.search);return p.get(n)||f}function todayISO(){return new Date().toISOString().slice(0,10)}function shiftISO(days){const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}function setRange(f,t){qs('from').value=f;qs('to').value=t;loadData()}function setToday(){setRange(todayISO(),todayISO())}function setYesterday(){const y=shiftISO(-1);setRange(y,y)}function setLast7(){setRange(shiftISO(-6),todayISO())}function rangeQuery(){return 'from='+encodeURIComponent(qs('from').value)+'&to='+encodeURIComponent(qs('to').value)+'&status='+encodeURIComponent(qs('status').value)+'&user='+encodeURIComponent(qs('user').value)}function nav(page){if(page==='manual_flight.php')location.href=page+'?date='+encodeURIComponent(qs('from').value||todayISO())+'&status='+encodeURIComponent(qs('status').value)+'&user='+encodeURIComponent(qs('user').value);else location.href=page+'?'+rangeQuery()}function fmt(v){if(!v)return '';let s=String(v).replace('T',' '),d=s.slice(0,10).split('-');return d.length===3?`${d[2]}.${d[1]}.${d[0]} ${s.slice(11,16)}`:s}function fmtDate(v){if(!v)return '';let d=String(v).slice(0,10).split('-');return d.length===3?`${d[2]}.${d[1]}.${d[0]}`:v}function addMin(v,m){if(!v||!m)return '';let d=new Date(String(v).replace(' ','T'));if(isNaN(d))return '';d.setMinutes(d.getMinutes()+parseInt(m,10));let p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())+':00'}async function postJson(url,data){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let j=await r.json();if(!j.ok)alert(j.error||'Fehler');return j}qs('from').value=getParam('from',getParam('date',todayISO()));qs('to').value=getParam('to',qs('from').value);qs('status').value=getParam('status','pending');qs('user').value=getParam('user','demo');let flightTypes=[],towTypes=[],gliderChargeModes=[],towChargeModes=[],towOwnChargeModes=[];async function loadLists(){if(!flightTypes.length)flightTypes=(await (await fetch('../src/api_flight_types.php?category=glider')).json()).flight_types||[];if(!towTypes.length)towTypes=(await (await fetch('../src/api_flight_types.php?category=tow')).json()).flight_types||[];if(!gliderChargeModes.length)gliderChargeModes=(await (await fetch('../src/api_charge_modes.php?context=glider')).json()).charge_modes||[];if(!towChargeModes.length)towChargeModes=(await (await fetch('../src/api_charge_modes.php?context=tow_charge')).json()).charge_modes||[];if(!towOwnChargeModes.length)towOwnChargeModes=(await (await fetch('../src/api_charge_modes.php?context=towplane_own')).json()).charge_modes||[]}function opts(list,current,label){let h='<option value="">Bitte wählen</option>';list.forEach(x=>{let s=String(x.id)===String(current??'')?' selected':'';h+=`<option value="${esc(x.id)}"${s}>${esc(label?label(x):(x.display_name||x.name))}</option>`});return h}function ftOpts(list,current){return opts(list,current,x=>x.code+' - '+x.name)}function syncCharge(op){let g=document.querySelector(`[data-op="${op}"][data-type="glider"]`);if(!g)return;let p=g.dataset.prefix,sel=qs(p+'charge'),val=sel?sel.value:'',txt=sel&&sel.selectedIndex>=0?sel.options[sel.selectedIndex].text:'';document.querySelectorAll(`[data-op="${op}"][data-sync-charge="1"]`).forEach(el=>{let mp=el.dataset.prefix;if(qs(mp+'charge'))qs(mp+'charge').value=val;if(qs(mp+'chargeLabel'))qs(mp+'chargeLabel').textContent=txt||'wie Segelflug'})}async function updateEntry(p,id,type){let d={entity:'accounting_entry',id,user:qs('user').value||'unknown'};if(type==='glider'){d.pilot_name=qs(p+'pilot').value;d.attendant_name=qs(p+'att').value;d.flight_minutes=qs(p+'min').value;d.vf_flight_type_id=qs(p+'ft').value;d.charge_mode=qs(p+'charge').value;d.comment=qs(p+'comment').value}else{d.tow_pilot_name=qs(p+'towpilot').value;d.tow_minutes=qs(p+'towmin').value;d.flight_minutes=qs(p+'flightmin').value;d.vf_flight_type_id=qs(p+'ft').value;d.charge_mode=qs(p+'charge').value;d.comment=qs(p+'comment').value}return postJson('../src/api_update_flight_data.php',d)}async function approveOperation(op){syncCharge(op);let tasks=[];document.querySelectorAll(`[data-op="${op}"][data-entry]`).forEach(el=>tasks.push(updateEntry(el.dataset.prefix,el.dataset.entry,el.dataset.type)));for(const t of tasks)await t;await postJson('../src/api_approve_flight_operation.php',{operation_id:op,action:'approve',user:qs('user').value||'unknown'});location.hash='op-'+op;loadData()}function requestCorrection(op){location.href='flight_correction.php?operation_id='+encodeURIComponent(op)+'&'+rangeQuery()}async function deletePart(op,part){if(!confirm((part==='glider'?'Segelflug':'Motorflug')+' wirklich löschen?'))return;let r=await fetch('../src/api_delete_flight_part.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation_id:op,part})});let j=await r.json();if(!j.ok){alert(j.error||'Fehler beim Löschen');return}loadData()}function attachTow(op){location.href='manual_flight.php?'+rangeQuery()+'&mode=attachTow&operation_id='+op}function attachGlider(op){location.href='manual_flight.php?'+rangeQuery()+'&mode=attachGlider&operation_id='+op}function renderGlider(r,op){let e=r.glider_entry;if(!e)return '<div class="col leftcol"><h3>Segelflug</h3><p class="small">Kein Segelflug zugeordnet.</p></div>';let p='g'+e.id+'_';return `<div class="col leftcol" data-op="${op}" data-entry="${e.id}" data-type="glider" data-prefix="${p}"><h3>Segelflug ${esc(e.callsign||'')}</h3><div class="timebox"><b>Start:</b> ${fmt(e.departure_time)}<br><b>Landung:</b> ${fmt(e.arrival_time)}<br><b>Flugzeit:</b> ${esc(e.flight_minutes||'')} min</div><div class="row"><label>Segelflugpilot<input id="${p}pilot" value="${esc(e.pilot_name||'')}"></label><label>Begleiter / FI<input id="${p}att" value="${esc(e.attendant_name||'')}"></label></div><div class="row"><label>Flugart<select id="${p}ft">${ftOpts(flightTypes,e.vf_flight_type_id)}</select></label><label>Abrechnung<select id="${p}charge" onchange="syncCharge(${op})">${opts(gliderChargeModes,e.charge_mode)}</select></label></div><label>Kommentar<textarea id="${p}comment">${esc(e.comment||'')}</textarea></label><input id="${p}min" type="hidden" value="${esc(e.flight_minutes||'')}"></div>`}function renderMotor(r,op){let e=r.tow_charge||r.towplane_own;if(!e)return '<div class="col rightcol"><h3>Motorflug</h3><p class="small">Kein Motorflug zugeordnet.</p></div>';let isCharge=e.entry_type==='tow_charge',p='m'+e.id+'_',cm=isCharge?towChargeModes:towOwnChargeModes,landing=e.arrival_time||(isCharge?addMin(e.departure_time,e.tow_minutes):''),flight=e.flight_minutes||(isCharge?e.tow_minutes:'');let ch=isCharge?`<label>Abrechnung<span id="${p}chargeLabel" class="small">wie Segelflug</span><input id="${p}charge" type="hidden" value="${esc(e.charge_mode||'')}"></label>`:`<label>Abrechnung<select id="${p}charge">${opts(cm,e.charge_mode||2)}</select></label>`;return `<div class="col rightcol" data-op="${op}" data-entry="${e.id}" data-type="tow" data-sync-charge="${isCharge?'1':'0'}" data-prefix="${p}"><h3>${isCharge?'Motorflug / F-Schlepp':'Motorflug'} ${esc(e.tow_callsign||e.callsign||'')}</h3><div class="timebox"><b>Start:</b> ${fmt(e.departure_time)}<br><b>Landung:</b> ${fmt(landing)}<br><b>Flugzeit:</b> ${esc(flight||'')} min<br><b>Schleppzeit:</b> ${esc(e.tow_minutes||'')} min</div><div class="row"><label>Motorpilot<input id="${p}towpilot" value="${esc(e.tow_pilot_name||'')}"></label></div><div class="row"><label>Flugart<select id="${p}ft" ${isCharge?'disabled':''}>${ftOpts(towTypes,e.vf_flight_type_id||(isCharge?3:''))}</select></label>${ch}</div><label>Kommentar<textarea id="${p}comment">${esc(e.comment||'')}</textarea></label><input id="${p}towmin" type="hidden" value="${esc(e.tow_minutes||'')}"><input id="${p}flightmin" type="hidden" value="${esc(flight||'')}"></div>`}function actions(op){return `<div class="row action-row action-row-top"><button class="warn" onclick="deletePart(${op},'glider')">Segelflug löschen</button><button class="warn" onclick="requestCorrection(${op})">Korrektur</button><button class="warn" onclick="deletePart(${op},'motor')">Motorflug löschen</button></div><div class="row action-row action-row-bottom"><button class="ok" onclick="approveOperation(${op})">Speichern & Freigeben</button></div>`}async function loadData(){history.replaceState(null,'',location.pathname+'?'+rangeQuery()+location.hash);qs('rangeLabel').innerHTML='<b>Zeitraum:</b> '+fmtDate(qs('from').value)+' bis '+fmtDate(qs('to').value);await loadLists();let d=await (await fetch('../src/api_flight_approvals.php?'+rangeQuery()+'&_='+Date.now())).json();qs('metrics').innerHTML=`<div class="metric"><span>pending</span><b>${d.counts.pending}</b></div><div class="metric"><span>Korrektur</span><b>${d.counts.correction_required}</b></div><div class="metric"><span>approved</span><b>${d.counts.approved}</b></div><div class="metric"><span>Alle</span><b>${d.counts.all}</b></div>`;let root=qs('list');root.innerHTML='';d.rows.forEach(x=>{let op=x.operation,div=document.createElement('div');div.className='card';div.id='op-'+op.id;let extra='';if(x.needs_tow_for_glider)extra+=`<div class="missing"><b>Kein Motorflug/Schlepp vorhanden.</b><br><button class="action" onclick="attachTow(${op.id})">Schlepp zu Segelflug erfassen</button></div>`;if(x.needs_glider_for_towplane)extra+=`<div class="missing"><b>Kein Segelflug zu diesem Motorflug vorhanden.</b><br><button class="action" onclick="attachGlider(${op.id})">Segelflug zu Schleppflug erfassen</button></div>`;div.innerHTML=`<div><span class="badge ${esc(x.status)}">${esc(x.status)}</span> <b>Operation ${esc(op.id)}</b> ${esc(op.kind||'')} ${esc(op.takeoff_time||'')}</div><div class="row">${renderGlider(x,op.id)}${renderMotor(x,op.id)}</div>${extra}${actions(op.id)}`;root.appendChild(div);syncCharge(op.id)});if(!d.rows.length)root.innerHTML='<div class="card">Keine Einträge im aktuellen Filter.</div>';if(location.hash){let el=document.querySelector(location.hash);if(el){el.classList.add('highlight');el.scrollIntoView({behavior:'smooth',block:'center'})}}if(window.lszjI18n)window.lszjI18n.translateAll()}loadData();
</script><script src="ktrax_import_range.js"></script>
